{
  "name": "checkout-service",
  "private": true,
  "scripts": {
    "lint": "eslint .",
    "test": "vitest run",
    "build": "vite build && cp release/deploy.sh dist/deploy.sh"
  },
  "devDependencies": {
    "eslint": "9.0.0",
    "vitest": "3.0.0",
    "vite": "6.0.0"
  }
}

{
  "baseline": {
    "event": {
      "name": "push",
      "ref": "refs/heads/main",
      "sha": "commit-43",
      "repository": "acme/checkout",
      "actor": "developer",
      "paths": [
        "backend/app.js"
      ]
    },
    "checks": {
      "lint": {
        "passed": true,
        "message": "lint fixture passed"
      },
      "unit": {
        "passed": true,
        "message": "unit fixture passed"
      },
      "build": {
        "passed": true,
        "message": "build fixture passed"
      },
      "integration": {
        "passed": true,
        "message": "integration fixture passed"
      },
      "audit": {
        "passed": true,
        "message": "audit fixture passed"
      },
      "smoke": {
        "passed": true,
        "message": "smoke fixture passed"
      }
    },
    "runners": [
      {
        "name": "hosted-linux",
        "labels": [
          "ubuntu-latest"
        ],
        "group": "hosted",
        "os": "Linux",
        "ephemeral": true,
        "trusted": false,
        "available": true
      },
      {
        "name": "hosted-windows",
        "labels": [
          "windows-latest"
        ],
        "group": "hosted",
        "os": "Windows",
        "ephemeral": true,
        "trusted": false,
        "available": true
      },
      {
        "name": "release-worker",
        "labels": [
          "self-hosted",
          "linux",
          "release"
        ],
        "group": "production",
        "os": "Linux",
        "ephemeral": true,
        "trusted": true,
        "available": true
      },
      {
        "name": "legacy-worker",
        "labels": [
          "self-hosted",
          "linux"
        ],
        "group": "legacy",
        "os": "Linux",
        "ephemeral": false,
        "trusted": false,
        "available": true
      }
    ],
    "actionRefs": {
      "actions/checkout@v6": "checkout",
      "actions/setup-node@v7": "node",
      "actions/cache@v4": "cache",
      "actions/upload-artifact@v4": "upload",
      "actions/download-artifact@v4": "download",
      "aws-actions/configure-aws-credentials@v5": "oidc"
    }
  },
  "cases": [
    {
      "id": "overlap",
      "title": "Two PRs overlap",
      "description": "Two PRs overlap. Compare the evidence with the success criteria.",
      "github": {
        "event": {
          "name": "pull_request",
          "ref": "refs/heads/main",
          "sha": "commit-43",
          "repository": "acme/checkout",
          "actor": "developer",
          "paths": [
            "backend/app.js"
          ],
          "base": "main",
          "number": 7
        },
        "arrivals": [
          {
            "at": 0,
            "event": {
              "name": "pull_request",
              "ref": "refs/heads/main",
              "sha": "commit-43",
              "repository": "acme/checkout",
              "actor": "developer",
              "paths": [
                "backend/app.js"
              ],
              "number": 7
            }
          },
          {
            "at": 2,
            "event": {
              "name": "pull_request",
              "ref": "refs/heads/main",
              "sha": "commit-44",
              "repository": "acme/checkout",
              "actor": "developer",
              "paths": [
                "backend/app.js"
              ],
              "number": 7
            }
          },
          {
            "at": 3,
            "event": {
              "name": "pull_request",
              "ref": "refs/heads/main",
              "sha": "commit-45",
              "repository": "acme/checkout",
              "actor": "developer",
              "paths": [
                "backend/app.js"
              ],
              "number": 8
            }
          }
        ]
      }
    },
    {
      "id": "releases",
      "title": "Two overlapping production requests",
      "description": "Only two production requests overlap; do not assume FIFO guarantees for arbitrary queues.",
      "github": {
        "arrivals": [
          {
            "at": 0,
            "event": {
              "name": "push",
              "ref": "refs/heads/main",
              "sha": "commit-43",
              "repository": "acme/checkout",
              "actor": "developer",
              "paths": [
                "backend/app.js"
              ]
            }
          },
          {
            "at": 2,
            "event": {
              "name": "push",
              "ref": "refs/heads/main",
              "sha": "commit-44",
              "repository": "acme/checkout",
              "actor": "developer",
              "paths": [
                "backend/app.js"
              ]
            }
          }
        ]
      }
    }
  ]
}

